INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Computernetz immer kabelgebunden?', 2, '[{"text": "Nein", "correct": true, "because": "WLAN ist drahtlos"}, {"text": "Ja", "correct": false, "because": "Drahtlose Netze existieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Netzwerk?', 3, '[{"text": "Ressourcen teilen", "correct": true, "because": "Effiziente Nutzung"}, {"text": "Software entwickeln", "correct": false, "because": "Nicht primär"}, {"text": "Hardware reparieren", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zu einem Netzwerk?', 5, '[{"text": "Router", "correct": true, "because": "Leitet Daten"}, {"text": "Switches", "correct": true, "because": "Verbindet Geräte"}, {"text": "Grafikkarten", "correct": false, "because": "Kein Netzwerkteil"}, {"text": "Monitore", "correct": false, "because": "Nur Endgeräte"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein LAN ist lokal begrenzt. b) Es funktioniert ohne Protokolle.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Protokolle sind essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Netzwerkplanung?', 4, '[{"text": "Bandbreite", "correct": false, "because": "Entscheidend für Leistung"}, {"text": "Sicherheit", "correct": false, "because": "Schützt Daten"}, {"text": "Bürodekor", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Netzwerk immer einen Server braucht?', 2, '[{"text": "Nein", "correct": true, "because": "Peer-to-Peer möglich"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll nutze ich für die Datenübertragung?', 3, '[{"text": "TCP/IP", "correct": true, "because": "Standard für Kommunikation"}, {"text": "USB", "correct": false, "because": "Kein Netzwerkprotokoll"}, {"text": "HDMI", "correct": false, "because": "Für Video, nicht Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Netzwerk?', 5, '[{"text": "Datenfreigabe", "correct": true, "because": "Zentraler Zugriff"}, {"text": "Kommunikation", "correct": true, "because": "Ermöglicht Austausch"}, {"text": "Schnellere CPUs", "correct": false, "because": "Kein direkter Effekt"}, {"text": "Bessere Grafik", "correct": false, "because": "Nicht netzwerkrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Netzwerk braucht IP-Adressen. b) Es ist immer sicher. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sicherheit nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein funktionierendes Netzwerk?', 4, '[{"text": "Router", "correct": false, "because": "Leitet Daten"}, {"text": "Netzwerkkabel", "correct": false, "because": "Für kabelgebundene Netze"}, {"text": "3D-Drucker", "correct": true, "because": "Kein Netzwerkbestandteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein WAN kleiner als ein LAN?', 2, '[{"text": "Nein", "correct": true, "because": "WAN ist größer"}, {"text": "Ja", "correct": false, "because": "LAN ist lokal"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Geräte verbinde ich typischerweise?', 4, '[{"text": "Computer", "correct": true, "because": "Grundbestandteil"}, {"text": "Drucker", "correct": true, "because": "Ressourcenfreigabe"}, {"text": "Kühlschrank", "correct": false, "because": "Selten vernetzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Netzwerk ohne Switch nicht geht. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Hub oder direkt möglich"}, {"text": "Ja", "correct": false, "because": "Switch nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Einrichtung?', 3, '[{"text": "Sicherheitsmaßnahmen", "correct": true, "because": "Schützt vor Angriffen"}, {"text": "Schöne Kabel", "correct": false, "because": "Ästhetik unwichtig"}, {"text": "Maximale Reichweite", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Netzwerk nutzt das OSI-Modell. b) Es ist immer drahtlos.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Protokolle sind essenziell?', 5, '[{"text": "TCP", "correct": true, "because": "Zuverlässige Übertragung"}, {"text": "IP", "correct": true, "because": "Adressierung"}, {"text": "Bluetooth", "correct": false, "because": "Anderer Bereich"}, {"text": "USB", "correct": false, "because": "Kein Netzwerkprotokoll"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Verwaltung unwichtig?', 3, '[{"text": "IP-Konfiguration", "correct": false, "because": "Notwendig für Kommunikation"}, {"text": "Firewall", "correct": false, "because": "Schützt das Netz"}, {"text": "Bildschirmgröße", "correct": true, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Läuft ein Netzwerk ohne IP-Adressen?', 3, '[{"text": "Nein", "correct": true, "because": "Adressierung nötig"}, {"text": "Ja", "correct": false, "because": "Nur in Spezialfällen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Netzwerk immer schnell ist?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Infrastruktur"}, {"text": "Ja", "correct": false, "because": "Geschwindigkeit variiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Topologie wähle ich für ein kleines Büro?', 4, '[{"text": "Stern", "correct": true, "because": "Einfach und skalierbar"}, {"text": "Ring", "correct": false, "because": "Komplexer"}, {"text": "Bus", "correct": false, "because": "Veraltet"}]');
